// Package edge manages the reverse proxy that routes project domains and the
// agent's webhook endpoint.
//
// The proxy is a Compose project ("ki-edge") generated by the agent and run
// with host networking. It gets no Docker socket: routing comes only from a
// file-provider document the agent rewrites whenever exposures or container
// addresses change. The pure generators ([Static], [Dynamic], [Compose]) live
// in this file; [Manager] drives them.
package edge

import (
	"encoding/json"
	"fmt"
	"net"
	"net/url"
	"path"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/open-southeners/ki/internal/edge/certs"
)

// DefaultImage is the pinned proxy image used when edge.image is empty.
const DefaultImage = "traefik:v3.7.14"

// ProjectName is the Compose project of the edge.
const ProjectName = "ki-edge"

// Labels on the edge container. It carries runtime.LabelManaged but, being a
// system component, no project label.
const (
	// LabelComponent identifies the edge container.
	LabelComponent = "ki.component"
	// ComponentEdge is the LabelComponent value of the edge.
	ComponentEdge = "edge"
	// labelConfigHash changes whenever the static configuration changes, so
	// Compose recreates the container (the proxy does not reload it).
	labelConfigHash = "ki.edge.config"
)

// Paths inside the proxy container.
const (
	ctrStatic     = "/etc/traefik/traefik.yaml"
	ctrDynamic    = "/etc/traefik/dynamic"
	ctrCerts      = "/etc/traefik/certs"
	ctrSelfSigned = "/etc/traefik/selfsigned"
	ctrACME       = "/data"
	ctrACMEFile   = "/data/acme.json"
)

// Router priorities. Server routes (on server hostnames and IP literals) beat
// project routes. There is deliberately no catch-all on arbitrary hosts: a
// path-limited project domain must never fall through to the agent.
const (
	prioServer  = 20000
	prioProject = 10000
	// prioServerRoot is the "/" panel route: below the specific server
	// routes (/hooks/, /rpc, /auth/) but still above project routes.
	prioServerRoot = 19999
)

const (
	resolver       = "le"
	webhooksSvc    = "ki-webhooks"
	panelSvc       = "ki-panel"
	rpcPath        = "/rpc"
	authPrefix     = "/auth/"
	entryWeb       = "web"
	entrySecure    = "websecure"
	hooksPrefix    = "/hooks/"
	maxRuleElement = 512
)

// StaticOptions parameterize [Static].
type StaticOptions struct {
	HTTPPort  int
	HTTPSPort int
	// ACMEEmail is the optional ACME account contact.
	ACMEEmail string
	// Behind selects behind mode: a single plain-HTTP entry point on
	// BehindListen (loopback host:port) for a front proxy that terminates
	// TLS. HTTPPort, HTTPSPort and ACMEEmail are ignored.
	Behind       bool
	BehindListen string
}

// forwardedTrusted are the sources whose X-Forwarded-* headers the proxy
// trusts in behind mode: the front proxy on the same host.
var forwardedTrusted = []string{"127.0.0.1/32", "::1/128"}

// staticBehind renders the behind-mode static configuration: one plain HTTP
// entry point bound to the loopback listen address, no HTTPS entry point, no
// redirect and no ACME resolver.
func staticBehind(listen string) ([]byte, error) {
	host, port, err := net.SplitHostPort(listen)
	if err != nil {
		return nil, fmt.Errorf("edge: invalid behind listen address %q", listen)
	}
	ip := net.ParseIP(host)
	if n, err := strconv.Atoi(port); ip == nil || !ip.IsLoopback() || err != nil || n < 1 || n > 65535 {
		return nil, fmt.Errorf("edge: behind listen address %q must be a loopback host:port", listen)
	}
	doc := map[string]any{
		"global": map[string]any{"checkNewVersion": false, "sendAnonymousUsage": false},
		"log":    map[string]any{"level": "INFO"},
		"entryPoints": map[string]any{
			entryWeb: map[string]any{
				"address":          listen,
				"forwardedHeaders": map[string]any{"trustedIPs": forwardedTrusted},
			},
		},
		"providers": map[string]any{"file": map[string]any{"directory": ctrDynamic, "watch": true}},
	}
	return marshalYAML(doc)
}

// Static renders the proxy's static configuration (traefik.yaml): the two
// entry points (plain HTTP redirects to HTTPS), the file provider watching the
// dynamic directory and the ACME resolver using the HTTP challenge.
func Static(o StaticOptions) ([]byte, error) {
	if o.Behind {
		return staticBehind(o.BehindListen)
	}
	if o.HTTPPort < 1 || o.HTTPPort > 65535 || o.HTTPSPort < 1 || o.HTTPSPort > 65535 {
		return nil, fmt.Errorf("edge: invalid ports %d/%d", o.HTTPPort, o.HTTPSPort)
	}
	if strings.ContainsAny(o.ACMEEmail, " \t\r\n") {
		return nil, fmt.Errorf("edge: invalid ACME email %q", o.ACMEEmail)
	}
	acme := map[string]any{
		"storage":       ctrACMEFile,
		"httpChallenge": map[string]any{"entryPoint": entryWeb},
	}
	if o.ACMEEmail != "" {
		acme["email"] = o.ACMEEmail
	}
	doc := map[string]any{
		"global": map[string]any{"checkNewVersion": false, "sendAnonymousUsage": false},
		"log":    map[string]any{"level": "INFO"},
		"entryPoints": map[string]any{
			entryWeb: map[string]any{
				"address": ":" + strconv.Itoa(o.HTTPPort),
				"http": map[string]any{"redirections": map[string]any{"entryPoint": map[string]any{
					"to": entrySecure, "scheme": "https", "permanent": true,
				}}},
			},
			entrySecure: map[string]any{"address": ":" + strconv.Itoa(o.HTTPSPort)},
		},
		"providers": map[string]any{"file": map[string]any{"directory": ctrDynamic, "watch": true}},
		"certificatesResolvers": map[string]any{
			resolver: map[string]any{"acme": acme},
		},
	}
	return marshalYAML(doc)
}

// ProjectRoute routes a set of domains (and an optional path prefix) to the
// running containers of one project service.
type ProjectRoute struct {
	Project string
	Service string
	Domains []string
	// Path is an optional path prefix ("" for none).
	Path string
	// Servers are the backend URLs, e.g. "http://172.18.0.2:8080".
	Servers []string
}

// InstalledCert is a static certificate served from the certs directory.
type InstalledCert struct {
	Hostname string
}

// ImportedCert is a bring-your-own certificate stored under certs/imported.
type ImportedCert struct {
	// ID names the files: imported/<ID>.crt and .key.
	ID string
	// Names are the certificate's DNS names (wildcards allowed).
	Names []string
	// Server makes the non-wildcard Names server hostnames.
	Server bool
}

// Model is the input of [Dynamic].
type Model struct {
	// WebhooksPort is the loopback port of the agent's webhook listener.
	WebhooksPort int
	// APIEdgePort is the loopback port of the API's edge listener
	// (api.edge_listen), the only upstream of the panel and RPC routes. It is
	// required when PanelEnabled or RPCPublic is set and ignored otherwise.
	APIEdgePort int
	// PanelEnabled adds the panel routes (/auth/, / including /setup) and
	// lets /rpc carry sessions. False routes none of them.
	PanelEnabled bool
	// RPCPublic adds /rpc even without the panel (api.public_tokens: bearer
	// tokens through the edge).
	RPCPublic bool
	// ACMEHostname is the standalone server domain ("" if none); it gets an
	// ACME certificate (in behind mode it is only a server hostname).
	ACMEHostname string
	// Behind renders behind mode: every router on the plain "web" entry
	// point without TLS, server routes on server hostnames only (no IP
	// literals), and no certificate store, since the front proxy owns TLS.
	Behind bool
	// Installed are the certificates installed for control-plane hostnames.
	Installed []InstalledCert
	// Imported are the bring-your-own certificates.
	Imported []ImportedCert
	// SelfSignedCert and SelfSignedKey are the file names (not paths) of the
	// default certificate inside the self-signed mount.
	SelfSignedCert, SelfSignedKey string
	Routes                        []ProjectRoute
}

// Dynamic renders the file-provider document: the webhook routes of the
// server's own hostnames and of unknown hosts, the project routes, the default
// certificate and the installed certificates. Output is deterministic.
func Dynamic(m Model) ([]byte, error) {
	if m.WebhooksPort < 1 || m.WebhooksPort > 65535 {
		return nil, fmt.Errorf("edge: invalid webhooks port %d", m.WebhooksPort)
	}
	routers := map[string]any{}
	services := map[string]any{
		webhooksSvc: lbService([]string{"http://127.0.0.1:" + strconv.Itoa(m.WebhooksPort)}),
	}
	// An installed certificate wins over ACME for the same hostname.
	acmeHost := m.ACMEHostname
	for _, c := range m.Installed {
		if c.Hostname == acmeHost {
			acmeHost = ""
		}
	}
	// routeTLS picks the TLS block for domains: the certificate store when
	// an installed or imported certificate covers every one of them, the
	// ACME resolver otherwise.
	var storedNames []string
	for _, c := range m.Installed {
		storedNames = append(storedNames, c.Hostname)
	}
	for _, c := range m.Imported {
		storedNames = append(storedNames, c.Names...)
	}
	routeTLS := func(domains []string) map[string]any {
		if m.Behind {
			return nil
		}
		for _, d := range domains {
			if !certs.Covers(storedNames, d) {
				return map[string]any{"certResolver": resolver}
			}
		}
		return map[string]any{}
	}
	apiRoutes := m.PanelEnabled || m.RPCPublic
	if apiRoutes {
		if m.APIEdgePort < 1 || m.APIEdgePort > 65535 {
			return nil, fmt.Errorf("edge: invalid API edge port %d", m.APIEdgePort)
		}
		services[panelSvc] = lbService([]string{"http://127.0.0.1:" + strconv.Itoa(m.APIEdgePort)})
	}
	entry := entrySecure
	if m.Behind {
		entry = entryWeb
	}
	// serverRoutes adds the agent routes for one group of hosts.
	serverRoutes := func(group, hosts string, tls map[string]any) {
		route := func(kind, rule, svc string, prio int) {
			r := map[string]any{
				"rule": hosts + " && " + rule, "priority": prio, "entryPoints": []string{entry},
				"service": svc,
			}
			if !m.Behind {
				r["tls"] = tls
			}
			routers["ki-"+kind+"-"+group] = r
		}
		route("hooks", "PathPrefix(`"+hooksPrefix+"`)", webhooksSvc, prioServer)
		if apiRoutes {
			route("rpc", "Path(`"+rpcPath+"`)", panelSvc, prioServer)
		}
		if m.PanelEnabled {
			route("auth", "PathPrefix(`"+authPrefix+"`)", panelSvc, prioServer)
			route("panel", "PathPrefix(`/`)", panelSvc, prioServerRoot)
		}
	}
	if acmeHost != "" {
		rule, err := hostRule([]string{acmeHost})
		if err != nil {
			return nil, err
		}
		serverRoutes("acme", rule, routeTLS([]string{acmeHost}))
	}
	var installedHosts []string
	for _, c := range m.Installed {
		installedHosts = append(installedHosts, c.Hostname)
	}
	for _, c := range m.Imported {
		if !c.Server {
			continue
		}
		for _, n := range c.Names {
			if !strings.HasPrefix(n, "*.") {
				installedHosts = append(installedHosts, n)
			}
		}
	}
	sort.Strings(installedHosts)
	uniq := installedHosts[:0]
	for i, h := range installedHosts {
		if i == 0 || h != installedHosts[i-1] {
			uniq = append(uniq, h)
		}
	}
	installedHosts = uniq
	if len(installedHosts) > 0 {
		rule, err := hostRule(installedHosts)
		if err != nil {
			return nil, err
		}
		serverRoutes("installed", rule, map[string]any{})
	}
	// Requests addressed to an IP literal (the self-signed fallback) reach
	// the agent routes; any other unknown host does not.
	if !m.Behind {
		serverRoutes("ip", ipLiteralRule, map[string]any{})
	}

	routes := append([]ProjectRoute(nil), m.Routes...)
	sort.Slice(routes, func(i, j int) bool {
		if routes[i].Project != routes[j].Project {
			return routes[i].Project < routes[j].Project
		}
		if routes[i].Service != routes[j].Service {
			return routes[i].Service < routes[j].Service
		}
		return strings.Join(routes[i].Domains, ",") < strings.Join(routes[j].Domains, ",")
	})
	for _, r := range routes {
		if len(r.Servers) == 0 {
			continue
		}
		rule, err := r.Rule()
		if err != nil {
			return nil, err
		}
		name := routeName(r)
		if _, dup := routers[name]; dup {
			return nil, fmt.Errorf("edge: duplicate route %q", name)
		}
		servers := append([]string(nil), r.Servers...)
		sort.Strings(servers)
		for _, s := range servers {
			if err := checkServerURL(s); err != nil {
				return nil, err
			}
		}
		router := map[string]any{
			"rule": rule, "priority": prioProject, "entryPoints": []string{entry},
			"service": name,
		}
		if !m.Behind {
			router["tls"] = routeTLS(r.Domains)
		}
		routers[name] = router
		services[name] = lbService(servers)
	}

	tls := map[string]any{}
	if m.SelfSignedCert != "" && !m.Behind {
		tls["stores"] = map[string]any{"default": map[string]any{"defaultCertificate": map[string]any{
			"certFile": path.Join(ctrSelfSigned, m.SelfSignedCert),
			"keyFile":  path.Join(ctrSelfSigned, m.SelfSignedKey),
		}}}
	}
	var list []any
	var instHosts []string
	for _, c := range m.Installed {
		instHosts = append(instHosts, c.Hostname)
	}
	sort.Strings(instHosts)
	for _, h := range instHosts {
		if m.Behind {
			break
		}
		list = append(list, map[string]any{
			"certFile": path.Join(ctrCerts, h+".crt"),
			"keyFile":  path.Join(ctrCerts, h+".key"),
		})
	}
	imported := append([]ImportedCert(nil), m.Imported...)
	sort.Slice(imported, func(i, j int) bool { return imported[i].ID < imported[j].ID })
	for _, c := range imported {
		if m.Behind {
			break
		}
		if !certs.ValidID(c.ID) {
			return nil, fmt.Errorf("edge: invalid imported certificate id %q", c.ID)
		}
		list = append(list, map[string]any{
			"certFile": path.Join(ctrCerts, "imported", c.ID+".crt"),
			"keyFile":  path.Join(ctrCerts, "imported", c.ID+".key"),
		})
	}
	if len(list) > 0 {
		tls["certificates"] = list
	}
	doc := map[string]any{"http": map[string]any{"routers": routers, "services": services}}
	if len(tls) > 0 {
		doc["tls"] = tls
	}
	return marshalYAML(doc)
}

// ipLiteralRule matches a Host that is an IPv4 dotted quad or an IPv6 literal.
// Traefik matches Host/HostRegexp against the lower-cased host with the port
// removed and IPv6 brackets stripped, so the second alternative sees "::1";
// optional brackets are tolerated anyway.
const ipLiteralRule = "(HostRegexp(`^[0-9]{1,3}(\\.[0-9]{1,3}){3}$`) || " +
	"HostRegexp(`^\\[?[0-9a-f]*:[0-9a-f:.]*\\]?$`))"

// Rule builds the router rule of the route: Host(`a`) || Host(`b`) with an
// optional && PathPrefix(`/p`). It rejects anything that is not a valid
// hostname or a plain path.
func (r ProjectRoute) Rule() (string, error) {
	if len(r.Domains) == 0 {
		return "", fmt.Errorf("edge: route %s/%s has no domains", r.Project, r.Service)
	}
	rule, err := hostRule(r.Domains)
	if err != nil {
		return "", err
	}
	if r.Path != "" {
		p, err := quote(r.Path)
		if err != nil {
			return "", err
		}
		if !strings.HasPrefix(r.Path, "/") || strings.ContainsAny(r.Path, " ") {
			return "", fmt.Errorf("edge: invalid path %q", r.Path)
		}
		if len(r.Domains) > 1 {
			rule = "(" + rule + ")"
		}
		rule += " && PathPrefix(" + p + ")"
	}
	if len(rule) > maxRuleElement*4 {
		return "", fmt.Errorf("edge: route %s/%s rule too long", r.Project, r.Service)
	}
	return rule, nil
}

// hostRule joins Host(`d`) matchers with ||, in the given order, parenthesized
// when there is more than one.
func hostRule(domains []string) (string, error) {
	parts := make([]string, 0, len(domains))
	for _, d := range domains {
		if err := certs.ValidHostname(d); err != nil {
			return "", fmt.Errorf("edge: %w", err)
		}
		q, err := quote(d)
		if err != nil {
			return "", err
		}
		parts = append(parts, "Host("+q+")")
	}
	if len(parts) == 1 {
		return parts[0], nil
	}
	return "(" + strings.Join(parts, " || ") + ")", nil
}

// quote wraps s in backticks, rejecting backticks and control characters.
func quote(s string) (string, error) {
	if s == "" || len(s) > maxRuleElement {
		return "", fmt.Errorf("edge: invalid rule value %q", s)
	}
	for _, r := range s {
		if r == '`' || r < 0x20 || r == 0x7f {
			return "", fmt.Errorf("edge: invalid character in rule value %q", s)
		}
	}
	return "`" + s + "`", nil
}

func checkServerURL(s string) error {
	u, err := url.Parse(s)
	if err != nil || u.Scheme != "http" || net.ParseIP(u.Hostname()) == nil || u.Port() == "" {
		return fmt.Errorf("edge: invalid backend %q", s)
	}
	return nil
}

func lbService(servers []string) map[string]any {
	list := make([]any, 0, len(servers))
	for _, s := range servers {
		list = append(list, map[string]any{"url": s})
	}
	return map[string]any{"loadBalancer": map[string]any{"servers": list}}
}

// routeName is a stable, file-provider-safe name for a project route. The
// suffix is a short checksum of the unsanitized identity so distinct names that
// sanitize alike never collide.
func routeName(r ProjectRoute) string {
	id := r.Project + "\x00" + r.Service + "\x00" + strings.Join(r.Domains, ",") + "\x00" + r.Path
	return "p-" + sanitize(r.Project) + "-" + sanitize(r.Service) + "-" + shortHash(id)
}

func sanitize(s string) string {
	return strings.Map(func(r rune) rune {
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' {
			return r
		}
		return '_'
	}, strings.ToLower(s))
}

// ComposeOptions parameterize [Compose].
type ComposeOptions struct {
	Image string
	// Dir is the edge data directory (<data_dir>/edge) on the host.
	Dir string
	// SelfSignedCert and SelfSignedKey are the file names inside Dir.
	SelfSignedCert, SelfSignedKey string
	// ConfigHash identifies the static configuration; changing it recreates
	// the container.
	ConfigHash string
}

// Compose renders the compose.json of the edge: host networking, read-only
// root filesystem and configuration mounts, all capabilities dropped except
// binding low ports and reading the agent-owned 0600 key files.
func Compose(o ComposeOptions) ([]byte, error) {
	if o.Image == "" || !path.IsAbs(o.Dir) || strings.ContainsAny(o.Dir, "\x00\n") {
		return nil, fmt.Errorf("edge: invalid compose options")
	}
	bind := func(src, dst string, ro bool) map[string]any {
		return map[string]any{
			"type": "bind", "source": src, "target": dst, "read_only": ro,
			"bind": map[string]any{"create_host_path": false},
		}
	}
	svc := map[string]any{
		"image":        o.Image,
		"network_mode": "host",
		"restart":      "unless-stopped",
		"read_only":    true,
		"tmpfs":        []string{"/tmp"},
		"security_opt": []string{"no-new-privileges:true"},
		"cap_drop":     []string{"ALL"},
		// DAC_OVERRIDE: the proxy runs as root but the key files are
		// 0600 and owned by the agent's user.
		"cap_add": []string{"NET_BIND_SERVICE", "DAC_OVERRIDE"},
		"labels": map[string]string{
			"ki.managed":    "true",
			LabelComponent:  ComponentEdge,
			labelConfigHash: o.ConfigHash,
		},
		"volumes": []any{
			bind(path.Join(o.Dir, "traefik.yaml"), ctrStatic, true),
			bind(path.Join(o.Dir, "dynamic"), ctrDynamic, true),
			bind(path.Join(o.Dir, "certs"), ctrCerts, true),
			bind(path.Join(o.Dir, o.SelfSignedCert), path.Join(ctrSelfSigned, o.SelfSignedCert), true),
			bind(path.Join(o.Dir, o.SelfSignedKey), path.Join(ctrSelfSigned, o.SelfSignedKey), true),
			bind(path.Join(o.Dir, "acme"), ctrACME, false),
		},
	}
	doc := map[string]any{"name": ProjectName, "services": map[string]any{"traefik": svc}}
	b, err := json.MarshalIndent(doc, "", "  ") // map keys are sorted
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

func marshalYAML(v any) ([]byte, error) {
	b, err := yaml.Marshal(v)
	if err != nil {
		return nil, fmt.Errorf("edge: render yaml: %w", err)
	}
	return b, nil
}
